sksl:
#version 300
uniform shader image;
uniform float2 size;
uniform float2 layer;
uniform float3x3 fromLayer;
uniform float3x3 toLayer;
uniform float4 screen;
uniform float time;
float2 amzCoord;
float4 amzOutput;
float2 amzScreenNorm() { float2 p=amzCoord-screen.xy; return float2(p.x/screen.z,1.0-p.y/screen.w); }
float2 amzLayerNorm() { float3 p=toLayer*float3(amzCoord,1.0); float2 n=p.xy/p.z/layer; return float2(n.x,1.0-n.y); }
float2 amzLayerCenter() { float3 p=fromLayer*float3(layer*.5,1.0); return p.xy/p.z-screen.xy; }
float4x4 amzRowMatrix(float3x3 m) { return float4x4(m[0].x,m[1].x,0.0,m[2].x, m[0].y,m[1].y,0.0,m[2].y, 0.0,0.0,1.0,0.0, m[0].z,m[1].z,0.0,m[2].z); }
float4x4 amzLayerToScreen() {
    float3x3 toNorm=float3x3(1.0/screen.z,0.0,0.0, 0.0,-1.0/screen.w,0.0,-screen.x/screen.z,1.0+screen.y/screen.w,1.0);
    float3x3 toPixels=float3x3(layer.x,0.0,0.0, 0.0,-layer.y,0.0, 0.0,layer.y,1.0);
    return amzRowMatrix(toNorm*fromLayer*toPixels);
}
float4x4 amzScreenToLayer() {
    float3x3 toPixels=float3x3(screen.z,0.0,0.0, 0.0,-screen.w,0.0, screen.x,screen.y+screen.w,1.0);
    float3x3 toNorm=float3x3(1.0/layer.x,0.0,0.0, 0.0,-1.0/layer.y,0.0,0.0,1.0,1.0);
    return amzRowMatrix(toNorm*toLayer*toPixels);
}
float2 getTexSize(float2 v) { return v; }
int amzIntMax(int a,int b) { return int(max(float(a),float(b))); }
int amzIntMin(int a,int b) { return int(min(float(a),float(b))); }
int amzIntAbs(int a) { return int(abs(float(a))); }
int amzIntClamp(int a,int b,int c) { return int(clamp(float(a),float(b),float(c))); }
const int amzPass=0;
uniform float amzIteration;
float4 amzSample_inputImg(float2 uv) { return float4(image.eval((float2(uv.x,1.0-uv.y)*screen.zw+screen.xy)/1.0)); }
float4 amzTexture(int tex,float2 uv) { if(tex==0) return amzSample_inputImg(uv);return float4(0.0); }
uniform float amzp_mode;
uniform float2 amzp_fromP;
uniform float2 amzp_toP;
uniform float amzp_reach;
uniform float amzp_radius;
uniform float amzp_softness;
uniform float amzp_autop;
uniform float amzp_autoSpeed;
uniform float amzp_progress;
uniform float amzp_drips;
uniform float amzp_spread;
uniform float amzp_pull;
uniform float amzp_tipShape;
uniform float amzp_taper;
uniform float amzp_bounce;
uniform float amzp_lenVar;
uniform float amzp_delayVar;
uniform float amzp_wobble;
uniform float amzp_dripSeed;
uniform float amzp_steps;
uniform float amzp_overdrawOn;
    float2 l2s(float2 v) { return (float4(v, 0.0, 1.0) * amzLayerToScreen()).xy; }
    float tipW(float x, float so) {
        float e = 1.0 - smoothstep(1.0 - max(so, 0.02), 1.0, x);
        if (int(amzp_tipShape) == 1) return sqrt(max(1.0 - x * x, 0.0)) * e;
        if (int(amzp_tipShape) == 2) return max(1.0 - x, 0.0) * e;
        return 1.0 - smoothstep(1.0 - so, 1.0, x);
    }
    float h1(float x) { return fract(sin(x * 127.1 + amzp_dripSeed * 17.31) * 43758.5453); }
    void nmMain() {
        float2 W = layer;
        float2 p = amzLayerNorm() * W;
        float pxs = screen.zw.x / max(screen.zw.x, 1.0);
        float2 F = W * 0.5 + float2(amzp_fromP.x, -amzp_fromP.y) * pxs;
        float2 T = W * 0.5 + float2(amzp_toP.x, -amzp_toP.y) * pxs;
        bool pin = p.x >= 0.0 && p.y >= 0.0 && p.x <= W.x && p.y <= W.y;
        if (int(amzp_mode) == 1) {
            float2 full = T - F;
            float LL = length(full);
            float2 ax = LL > 1e-3 ? full / LL : float2(0.0, -1.0);
            float2 nx = float2(-ax.y, ax.x);
            float nd = clamp(floor(amzp_drips + 0.5), 1.0, 12.0);
            float R = max(amzp_radius, 1.0) * pxs;
            float S = max(amzp_pull, 0.05) * R;
            float so = clamp(amzp_softness, 0.0, 1.0);
            float tp = clamp(amzp_taper, 0.0, 0.95) * (int(amzp_tipShape) == 1 ? 0.35 : 1.0);
            float sp = max(amzp_spread, 0.0) * pxs;
            float Tm = amzp_progress + ((amzp_autop>0.5) ? time * amzp_autoSpeed : 0.0);
            float2 q = p;
            for (int i = 0; i < 12; i++) {
                float fi = float(i);
                if (fi >= nd) break;
                float ha = h1(fi * 3.1 + 1.0), hb = h1(fi * 3.1 + 2.0), hc = h1(fi * 3.1 + 3.0), hd = h1(fi * 3.1 + 4.0);
                float lane = nd > 1.0 ? fi / (nd - 1.0) - 0.5 : 0.0;
                float off = (lane + (nd > 1.0 ? (ha - 0.5) * 0.6 / nd : 0.0)) * sp;
                float dl = nd > 1.0 ? hb * max(amzp_delayVar, 0.0) : 0.0, spd = nd > 1.0 ? mix(0.75, 1.3, hc) : 1.0;
                float uu = clamp((Tm - dl) * 0.55 * spd, 0.0, 1.0);
                float e = uu * uu * (2.0 - uu);
                float land = smoothstep(0.85, 1.0, uu);
                float tAfter = max(Tm - dl - 1.0 / (0.55 * spd), 0.0);
                float bo = clamp(amzp_bounce, 0.0, 1.0) * land * sin(tAfter * 6.0) * exp(-tAfter * 0.6);
                float Li = LL * (1.0 - (nd > 1.0 ? clamp(amzp_lenVar, 0.0, 1.0) * hd : 0.0)) * max(e + bo, 0.0);
                if (Li < 0.5) continue;
                float2 Fi = F + nx * off;
                float to = dot(q - Fi, ax);
                float lo = dot(q - Fi, nx);
                lo -= clamp(amzp_wobble, 0.0, 2.0) * R * 0.35 * sin(to / (R * 1.5) + ha * 6.2832 + Tm * 1.3) * clamp(to / max(Li, 1.0), 0.0, 1.0);
                if (to < -S - 1.0 || abs(lo) > R + 1.0 || to > Li + R * 3.0) continue;
                float u = to, la = lo;
                for (int k = 0; k < 4; k++) {
                    float w = tipW(abs(la) / R, so);
                    float A = Li * w;
                    float lo2 = to - A - 1.0, hi2 = to + 1.0;
                    for (int j = 0; j < 14; j++) {
                        float m = 0.5 * (lo2 + hi2);
                        if (m + A * smoothstep(-S, 0.0, m) < to) lo2 = m; else hi2 = m;
                    }
                    u = 0.5 * (lo2 + hi2);
                    la = lo / max(1.0 - tp * smoothstep(-S, 0.0, u) * w, 0.05);
                }
                q = Fi + ax * u + nx * la;
            }
            bool qinD = q.x >= 0.0 && q.y >= 0.0 && q.x <= W.x && q.y <= W.y;
            if (!qinD && ((amzp_overdrawOn>0.5) || !pin)) { amzOutput = float4(0.0); return; }
            amzOutput = amzTexture(0, l2s(clamp(q / W, 0.0, 1.0)));
            return;
        }
        float2 q = p;
        float so = clamp(amzp_softness, 0.0, 1.0);
        float n = clamp(floor(amzp_steps + 0.5), 1.0, 24.0);
        float2 D = (T - F) * max(amzp_reach, 0.0);
        float R = max(amzp_radius, 1.0) * pxs;
        float dd = max(dot(D, D), 1e-4);
        for (int k = 0; k < 24; k++) {
            if (float(k) >= n) break;
            float s = clamp(dot(q - F, D) / dd, 0.0, 1.0);
            float dist = length(q - F - D * s);
            float w = 1.0 - smoothstep(R * (1.0 - so), R + 0.5, dist);
            q -= D / n * w;
        }
        bool qin = q.x >= 0.0 && q.y >= 0.0 && q.x <= W.x && q.y <= W.y;
        if (!qin && ((amzp_overdrawOn>0.5) || !pin)) { amzOutput = float4(0.0); return; }
        float2 uv = clamp(q / W, 0.0, 1.0);
        amzOutput = amzTexture(0, l2s(uv));
    }
    void amzRender() {
        nmMain();
        if (!(amzp_overdrawOn>0.5)) amzOutput *= amzTexture(0, amzScreenNorm()).a;
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }
